const email = $input.first().json;

// We only want replies from domains we contacted. 
// But for now, we'll classify any unread email that has a body.
const sender = email.from.value[0].address;
const subject = email.subject || '';
const text = email.text || email.snippet || '';

if (!text) return [];

const systemPrompt = `Eres un clasificador de respuestas de correo para candidaturas espontáneas de empleo en hostelería.
Clasifica la respuesta en UNA de las siguientes categorías exactas:
- INTERVIEW (solicitan entrevista, llamada o prueba)
- INFO_REQUEST (piden más documentos, referencias o responder preguntas)
- REJECTED (rechazo general, no perfil)
- NO_VACANCY (no hay vacantes ahora, a veces guardan CV)
- NO_ACCOMMODATION (rechazo porque no ofrecen alojamiento)
- SWISS_RESIDENCE_REQUIRED (rechazo porque exigen permiso/residencia en Suiza)
- OTHER (respuestas automáticas, spam, no relacionadas)

Devuelve JSON estructurado.`;

const inputData = {
  sender: sender,
  subject: subject,
  body: text.substring(0, 3000) // limit length
};

const schemaInfo = `
Esquema requerido:
{
  "classification": "REJECTED",
  "confidence": 0.95,
  "reason": "Brief explanation of why"
}`;

return [{
  json: {
    message_id: email.id,
    sender: sender,
    subject: subject,
    prompt: JSON.stringify(inputData, null, 2) + schemaInfo,
    system: systemPrompt
  }
}];

const apiResponse = $input.first().json;
const meta = $('Prepare Groq').first().json;

let parsed;
try {
  parsed = JSON.parse(apiResponse.choices[0].message.content);
} catch(e) {
  parsed = { classification: 'OTHER', confidence: 0, reason: 'Parse error' };
}

return [{
  json: {
    message_id: meta.message_id,
    sender: meta.sender,
    subject: meta.subject,
    classification: parsed.classification,
    confidence: parsed.confidence,
    reason: parsed.reason,
    timestamp: new Date().toISOString()
  }
}];
